 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Lucy. How can I help you today?",
      "tags": ["greeting"]
    },
    {
      "speaker": "customer",
      "text": "Hello Lucy, mera network signal bahut kharab hai. I am not getting any calls on my phone 93184 43959.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I need your account number to check the status. Please provide it.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "My account number is 11527375 and my name is Vivek Das.",
      "tags": ["identity_verification"]
    },
    {
      "speaker": "agent",
      "text": "One moment. I am checking the network coverage in your area.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Please jaldi karo, it is very frustrating. I have been facing this for three days now.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "The system shows the network is working fine in your location.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Kya baat kar rahe ho? Signal bilkul nahi hai! I am paying for a service that I am not getting.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "The system is correct. You should restart your device.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Maine restart kar liya hai multiple times. This is ridiculous. I want a solution right now!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "There is nothing more I can do from my end if the system shows no outage.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "This is the worst service ever. Main switch kar raha hoon, I will port out to another provider immediately.",
      "tags": ["churn_signal"]
    },
    {
      "speaker": "agent",
      "text": "Is there anything else I can assist you with today? I have checked your account and found no issues. Goodbye.",
      "tags": ["closure"]
    }
  ]
}
